const f=-4,u=[{intervals:4,points:50},{intervals:3,points:30},{intervals:2,points:15},{intervals:1,points:5}];export const SACK=-5,INTERCEPTION=-10;export function pointsForPosition(t,r){for(const n of u)if(t>=-4+r*n.intervals)return n.points;return 0}export function ladderBands(t){const r=[...u].reverse().map(e=>({from:-4+t*e.intervals,points:e.points})),n=r.map((e,o)=>({from:e.from,to:o+1<r.length?r[o+1].from:1/0,points:e.points}));return[{from:-1/0,to:n[0].from,points:0},...n]}export function bandAt(t,r){const n=ladderBands(r);return n.find(e=>t>=e.from&&t<e.to)||n[0]}export function classifyPlay({ranWithBall:t,threwTo:r,ball:n,carrierX:e,lineInterval:o,reached50:a}){if(!t&&!r)return{result:"sack",points:SACK,headline:"Sacked",detail:"Nobody got the ball away in time."};if(!t){if(!n||!n.caught)return{result:"incomplete",points:0,headline:"Incomplete",detail:"The pass fell to the turf."};if(n.team!==0)return{result:"interception",points:INTERCEPTION,headline:"Intercepted",detail:"The Crows read it and took the ball away."};const s=pointsForPosition(e,o);return{result:"catch",points:s,headline:s===50?"All the way":"Caught",detail:s===50?"Caught and carried the whole way across.":`Caught and brought down for ${s}.`}}const i=pointsForPosition(e,o);return{result:a?"run-50":"run",points:i,headline:i===50?"All the way":"Kept it",detail:i===50?"Tucked it and ran the whole way across.":`Tucked it and ran for ${i}.`}}export function summarise(t){const r=t.reduce((e,o)=>e+o.points,0),n=t.reduce((e,o)=>o.points>e.points?o:e,t[0]||{points:0});return{total:r,plays:t.length,best:n?n.points:0,scored:t.filter(e=>e.points>0).length,gaveAway:t.filter(e=>e.points<0).length}}export function verdictFor(t){return t>=300?"A clinic.":t>=200?"A very good afternoon.":t>=120?"Solid work.":t>=60?"Moved the ball.":t>0?"Hard yards.":"One of those games."}export function nextStreak(t,r,{good:n=30,bad:e=0}={}){const o=Number.isFinite(t)?t:0;return r>=n?o>=0?o+1:1:r<=e?o<=0?o-1:-1:o>0?o-1:o<0?o+1:0}export function streakOver(t,r){let n=0;for(const e of t||[])n=nextStreak(n,e&&e.points||0,r);return n}export function difficultyFor(t,{run:r=3}={}){if(!(r>0)||!Number.isFinite(t))return 0;const n=t/r;return n>1?1:n<-1?-1:n}
